from pathlib import Path

def _load_holidays() -> set[str]:
    """Load all dates from VEVENT DTSTART in .ics files under calendars/"""
    holidays = set()
    base = Path(__file__).parent.parent / "calendars"
    if not base.exists():
        return holidays
    for file in base.glob("*.ics"):
        try:
            with open(file, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if line.startswith("DTSTART"):
                        # Handle various formats
                        if ":" in line:
                            _, value = line.split(":", 1)
                        else:
                            continue
                        # Strip parameters
                        if ";" in value:
                            _, date_part = value.split(";", 1)
                        else:
                            date_part = value
                        # Convert formats
                        if len(date_part) == 8:  # YYYYMMDD
                            try:
                                dt = datetime.datetime.strptime(date_part, "%Y%m%d")
                                holidays.add(dt.date().isoformat())
                            except Exception:
                                pass
                        elif len(date_part) == 10:  # YYYY-MM-DD
                            try:
                                dt = datetime.datetime.strptime(date_part, "%Y-%m-%d")
                                holidays.add(dt.date().isoformat())
                            except Exception:
                                pass
        except Exception:
            continue
    return holidays

