    directory and checks membership. If no calendars are present, it returns
    False for all dates.
    """
    # Basic validation
    try:
        datetime.datetime.strptime(date, "%Y-%m-%d")
    except Exception:
        raise ValueError("date must be in YYYY-MM-DD format")
    return date in _HOLIDAYS

def roman_to_int(s: str) -> int:
    """Convert a Roman numeral (I, V, X, L, C, D, M with subtractive pairs) to an integer."""
    if not s:
        return 0
    values = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    prev = 0
    for ch in reversed(s):
        val = values.get(ch, 0)
        if val < prev:
            total -= val
        else:
            total += val
            prev = val
    return total

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v):
        return tuple(int(part) for part in v.split('.'))
    return sorted(vs, key=key)

def merge_intervals(iv: list) -> list:
    """Merge overlapping [start, end] intervals; return them sorted by start. Touching intervals merge."""
    if not iv:
        return []
    # Sort by start
    iv_sorted = sorted(iv, key=lambda x: x[0])
    merged = [iv_sorted[0]]
    for curr in iv_sorted[1:]:
        last = merged[-1]
        # If current starts before or at the end of last (touching or overlapping)
        if curr[0] <= last[1]:
            # Merge by extending end if needed
            last[1] = max(last[1], curr[1])
        else:
            merged.append(curr)
    return merged

def camel_to_snake(s: str) -> str:
    """Convert camelCase or PascalCase to snake_case. Consecutive capitals stay together (HTTPServer -> http_server)."""
    if not s:
        return s
    result = []
    prev_lower = False
    for i, ch in enumerate(s):
        if ch.isupper():
            # Determine if we need underscore
            if i > 0 and not prev_lower:
                # If previous was lower or digit, add underscore
                if s[i-1].islower() or s[i-1].isdigit():
                    result.append('_')
            elif i > 0 and prev_lower:
                # previous was lower, underscore added already
                pass
            # Lowercase current char
            result.append(ch.lower())
            prev_lower = False
        else:
            result.append(ch)
            prev_lower = True
    return ''.join(result)

def parse_price(s: str) -> float:
    """Parse a US-formatted price string like '$1,200.50' into a float."""
    if not s:
        raise ValueError("empty string")
    # Remove leading $ and commas
    cleaned = s.lstrip('$').replace(',', '')
    try:
        return float(cleaned)
    except ValueError as e:
        raise ValueError(f"Invalid price format: {s}") from e

def run_length_encode(s: str) -> str:
    if not s:
        return ""
    result = []
    count = 1
    prev = s[0]
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append(f"{prev}{count}")
            prev = ch
            count = 1
    result.append(f"{prev}{count}")
    return "".join(result)

def c_to_f(c: float) -> float:
    """Convert Celsius to Fahrenheit (F = C * 9/5 + 32), rounded to 1 decimal."""
    return round(c * 9 / 5 + 32, 1)

def word_count(text: str) -> dict:
    """Count lowercase words (split on whitespace, strip .,!? from both ends)."""
    counts = {}
    for token in text.split():
        # strip leading/trailing punctuation .,!? (and possibly other) from both ends
        word = token.strip('.,!?')
        if not word:
            continue
        word = word.lower()
        counts[word] = counts.get(word, 0) + 1
    return counts

import os
from datetime import datetime

def _load_holidays():
    holidays = set()
    for root, _, files in os.walk("calendars"):
        for f in files:
            if not f.lower().endswith(".ics"):
                continue
            path = os.path.join(root, f)
            with open(path, "r", encoding="utf-8") as fp:
                for line in fp:
                    line = line.strip()
                    if line.upper().startswith("DTSTART"):
                        # line format: DTSTART:YYYYMMDD or DTSTART;VALUE=DATE:YYYYMMDD
                        parts = line.split(":", 1)
                        if len(parts) != 2:
                            continue
                        date_str = parts[1]
                        try:
                            # support date only format
                            dt = datetime.strptime(date_str, "%Y%m%d")
                            holidays.add(dt.date().isoformat())
                        except ValueError:
                            # try with timezone offset
                            try:
                                dt = datetime.strptime(date_str, "%Y%m%dT%H%M%SZ")
                                holidays.add(dt.date().isoformat())
                            except ValueError:
                                continue
    return holidays

_HOLIDAYS = _load_holidays()

def is_holiday(date: str) -> bool:
    """True if date is a company holiday per calendars/*.ics."""
    # date expected in YYYY-MM-DD
    return date in _HOLIDAYS
